const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path'),fs=require('fs');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{
const p=await b.newPage({viewport:{width:390,height:1000},reducedMotion:'no-preference'}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(require('./island-test-helper.cjs'));await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.evaluate(()=>{window.speak=()=>Promise.resolve();window.tone=()=>{}});await p.click('#learningTab');
for(const island of [0,1])for(let i=0;i<(island?6:8);i++){await p.evaluate(({island,i})=>{DEUTSCH_JOURNEY.select(island);DEUTSCH_JOURNEY.open(i)},{island,i});const portrait=p.locator('.market-encounter>.market-merchant').first();if(await portrait.evaluate(e=>getComputedStyle(e).animationName)!=='character-hello')throw Error('Missing character greeting '+island+':'+i);await p.click('#alContinue');if(await p.locator('.market-task-portrait').first().evaluate(e=>getComputedStyle(e).animationName)!=='none')throw Error('Character moves during answer');}
const complete=async(index,wrong=0,train=false)=>{await p.evaluate(({index,wrong,train})=>{const j=DEUTSCH_JOURNEY,a=DEUTSCH_ADAPTIVE;j.select(0);if(train){j.open(index);document.querySelector(index==='greetings'?'#greetingBegin':'#alContinue').click();finishTrainingToTest()}else j.test(index);let n=0;while(!a.snapshot().finished){const q=a.snapshot().queue[a.snapshot().index];a.answer(n++<wrong?'wrong':q.type==='ua'||q.type==='listen'?q.c.ua:q.c.de);document.querySelector('#alNext').click()}},{index,wrong,train})};
// Passing, correcting errors, training and perfection have distinct consequences.
await complete(0,1,true);if(!await p.evaluate(()=>DEUTSCH_JOURNEY.load().lessons[0].passed&&!DEUTSCH_JOURNEY.mastery()[1].earned))throw Error('A merely passed test earned a mastery award');
if(!await p.locator('.journey-recap').evaluate(e=>!e.closest('details')&&e.getBoundingClientRect().height>0))throw Error('Mistakes hidden');if(await p.locator('[data-mastery-new="true"]').count()||await p.locator('[data-mastery-owned="true"]').count())throw Error('94% celebrated perfection');
await p.click('#alCorrectMistakes');await p.evaluate(()=>{const a=DEUTSCH_ADAPTIVE;while(!a.snapshot().finished){const q=a.snapshot().queue[a.snapshot().index];a.answer(q.type==='ua'||q.type==='listen'?q.c.ua:q.c.de);document.querySelector('#alNext').click()}if(DEUTSCH_JOURNEY.mastery().some(a=>a.earned)||DEUTSCH_JOURNEY.load().lessons[0].best===100)throw Error('Corrections upgraded the frozen score')});
await complete(0);if(await p.locator('[data-mastery-new="true"]').count()!==1||!await p.evaluate(()=>DEUTSCH_JOURNEY.mastery()[1].earned))throw Error('Perfect test did not earn award');
if(await p.locator('[data-team-state="success"]>.market-merchant').evaluate(e=>getComputedStyle(e).animationName)!=='character-cheer')throw Error('Mentor does not celebrate');
fs.mkdirSync('audit-screenshots',{recursive:true});await p.evaluate(()=>{document.querySelectorAll('#learningView img').forEach(i=>i.loading='eager')});await p.locator('[data-mastery-award]').screenshot({path:'audit-screenshots/mastery-award-mentor.png',animations:'disabled'});await p.click('#alDone');if(!await p.locator('.compact-details[open] [data-mastery-item="2"][data-mastery-earned="true"]').count())throw Error('New award not revealed on map');
await complete(0);if(await p.locator('[data-mastery-new="true"]').count())throw Error('Duplicate reward celebration');await complete(0,18);if(!await p.evaluate(()=>DEUTSCH_JOURNEY.mastery()[1].earned)||await p.locator('[data-mastery-new="true"]').count())throw Error('Failed replay erased or re-awarded mastery');if(await p.locator('[data-team-state="encourage"]>.market-merchant').evaluate(e=>getComputedStyle(e).animationName)!=='character-encourage')throw Error('Mentor does not encourage');
await p.emulateMedia({reducedMotion:'reduce'});await complete(1,0,true);if(await p.locator('[data-team-state="success"]>.market-merchant').evaluate(e=>getComputedStyle(e).animationName)!=='none'||await p.locator('[data-mastery-new="true"] .mastery-emblem').evaluate(e=>getComputedStyle(e).animationName)!=='none')throw Error('Reduced motion animated reward');
for(const index of ['greetings',2,3,4,5,6,7])await complete(index,0,true);
if(!await p.evaluate(()=>DEUTSCH_JOURNEY.mastery().length===9&&DEUTSCH_JOURNEY.mastery().every(a=>a.earned))||!await p.locator('[data-mastery-title]').count())throw Error('Nine-award title missing, including ship');
await p.evaluate(()=>DEUTSCH_JOURNEY.map());if(await p.locator('.mastery-card[data-mastery-earned="true"]').count()!==9||await p.locator('[data-mastery-count]').textContent()!=='9 / 9')throw Error('Incomplete album');
await p.evaluate(()=>document.querySelector('.mastery-collection').closest('details').open=true);
for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:1000});if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Award album overflow '+width)}await p.setViewportSize({width:390,height:1000});await p.locator('.mastery-collection').screenshot({path:'audit-screenshots/mastery-award-album.png',animations:'disabled'});
// Old perfect scores are read as awards without rewriting any saved results.
const before=await p.evaluate(()=>{const j=DEUTSCH_JOURNEY;sessionStorage.setItem('masterySaved',profileStorage.getItem(j.key));sessionStorage.setItem('shipSaved',profileStorage.getItem(DEUTSCH_GREETINGS.key));return j.mastery().filter(a=>a.earned).length});await p.reload();await p.click('#learningTab');await p.evaluate(()=>{DEUTSCH_JOURNEY.select(0);if(DEUTSCH_JOURNEY.mastery().filter(a=>a.earned).length!==9)throw Error('Awards lost on reload');if(profileStorage.getItem(DEUTSCH_JOURNEY.key)!==sessionStorage.getItem('masterySaved')||profileStorage.getItem(DEUTSCH_GREETINGS.key)!==sessionStorage.getItem('shipSaved'))throw Error('Reading legacy awards rewrote grades')});
await p.evaluate(()=>{DEUTSCH_JOURNEY.open('greetings')});if(!await p.locator('[data-mastery-target]').textContent().then(s=>s.includes('Майстер привітань')))throw Error('Ship award target missing');
await p.evaluate(()=>{DEUTSCH_JOURNEY.map();document.querySelector('.team-roster').closest('details').open=true});if(await p.locator('.mentor-support').count()!==4)throw Error('Mentors lack roles');const roles=await p.locator('.mentor-support').allTextContents();if(roles.some(s=>s.length<30))throw Error('Roles are empty');await p.locator('[data-team-member="fox"] [data-team-open]').click();if(!await p.locator('[data-ship-chapter="greetings"]').count())throw Error('Fox does not lead to ship lesson');
await p.evaluate(()=>{document.documentElement.lang='en';DEUTSCH_JOURNEY.map()});if(!await p.locator('.mastery-collection').textContent().then(s=>s.includes('Island master')))throw Error('English award title missing');
await p.click('#profileButton');await p.fill('#profileAddInput','Mastery child');await Promise.all([p.waitForEvent('load'),p.click('#profileAddForm button')]);await p.click('#learningTab');await p.evaluate(()=>{DEUTSCH_JOURNEY.select(0);if(DEUTSCH_JOURNEY.mastery().some(a=>a.earned))throw Error('Awards leaked across profiles');DEUTSCH_JOURNEY.select(1);if(document.querySelector('.mastery-collection,[data-mastery-award],[data-mastery-target]'))throw Error('First-island awards leaked into second island')});
if(errors.length)throw Error(errors.join(';'));console.log('PASS character reactions and nine mentor awards: 94% versus 100%, frozen corrections, unique grants, failed replay retention, ship, title, roles, reload, profiles, localization and reduced motion');
}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
